/* HEXA BATTLEGROUNDS setup — PART 37 OF 57. Run parts in order. Safe to re-run. */ create or replace function player_state(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; a arenas; e events; mi mission_instances; mt mission_templates; v_mission jsonb; v_battle jsonb; bi mission_instances; b battles; v_clue jsonb; v_result jsonb; v_comms jsonb; v_out jsonb; v_scan boolean; v_hidden boolean; v_board jsonb; v_role_names jsonb; v_parts jsonb; begin p := _auth_player(p_token); select * into t from teams where id = p.team_id; perform _tick(t.arena_id); select * into p from players where id = p.id; select * into t from teams where id = p.team_id; select * into a from arenas where id = t.arena_id; select * into e from events where id = t.event_id; v_scan := t.scan_until is not null and t.scan_until > now(); select * into mi from mission_instances where team_id = t.id and status = 'active' and kind <> 'battle' order by created_at desc limit 1; if mi.id is not null then select * into mt from mission_templates where id = mi.template_id; v_mission := jsonb_build_object( 'id', mi.id, 'kind', mi.kind, 'title', mt.title, 'objective', mt.objective, 'category', mt.category, 'difficulty', mt.difficulty, 'deadline', mi.deadline, 'started_at', mi.started_at, 'attempts_left', mi.attempts_left, 'sync', mi.sync_round_id is not null, 'location', mi.location_id); if mt.relay then v_mission := v_mission || jsonb_build_object('relay', jsonb_build_object( 'partner', (select number from teams where id = mi.partner_team_id), 'fallback_at', mi.fallback_at)); end if; if p.role = 'captain' then select jsonb_agg(x -> 'label') into v_parts from jsonb_array_elements(mt.parts) x; v_mission := v_mission || jsonb_build_object('parts', v_parts, 'hint_cost', _cfg(e.id, 'hint_cost'), 'hint', case when mi.hint_used then mt.hint end, 'revealed', mi.revealed, 'reveal_cost', _reveal_cost(mi), 'revealable', (select jsonb_agg(not (x -> 'accept') ? '{KEY}') from jsonb_array_elements(mt.parts) x)); elsif p.role is not null then v_clue := mt.clues -> p.role; if (v_clue ? 'reveal_seconds') and now() > mi.started_at + _secs((v_clue ->> 'reveal_seconds')::int) then v_clue := v_clue || jsonb_build_object('body', '▒▒▒ SIGNAL LOST ▒▒▒\nThe flash has ended. Tell your captain what you remember.', 'expired', true); end if; v_mission := v_mission || jsonb_build_object('clue', v_clue); if p.role = 'intel' and mt.relay and mi.fallback_at is not null and now() >= mi.fallback_at then v_mission := v_mission || jsonb_build_object('relay_backup', mi.relay_key); end if; end if; end if; select * into bi from mission_instances where team_id = t.id and status = 'active' and kind = 'battle' limit 1; if bi.id is not null then select * into mt from mission_templates where id = bi.template_id; select * into b from battles where id = bi.battle_id; v_battle := jsonb_build_object('id', bi.id, 'battle_id', b.id, 'title', mt.title, 'objective', mt.objective, 'deadline', bi.deadline, 'started_at', bi.started_at, 'attempts_left', bi.attempts_left, 'weapon', b.weapon, 'damage', b.damage, 'attacker', (select number from teams where id = b.attacker_id), 'defender', (select number from teams where id = b.defender_id), 'we_attacked', b.attacker_id = t.id); if p.role = 'captain' then select jsonb_agg(x -> 'label') into v_parts from jsonb_array_elements(mt.parts) x; v_battle := v_battle || jsonb_build_object('parts', v_parts); elsif p.role is not null then v_battle := v_battle || jsonb_build_object('clue', mt.clues -> p.role); end if; end if; select jsonb_build_object('id', x.id, 'status', x.status, 'kind', x.kind, 'points', x.points_awarded, 'title', (select title from mission_templates where id = x.template_id), 'at', coalesce(x.solved_at, x.deadline)) into v_result from mission_instances x where x.team_id = t.id and x.status <> 'active' and coalesce(x.solved_at, least(x.deadline, now())) > now() - interval '20 seconds' order by coalesce(x.solved_at, x.deadline) desc limit 1; if p.role = 'captain' then select jsonb_build_object( 'messages', coalesce((select jsonb_agg(m order by m.at) from ( select cm.id, cm.body, cm.at, (select number from teams where id = cm.from_team) as from_number, (select number from teams where id = cm.to_team) as to_number, cm.from_team = t.id as mine from chat_messages cm where cm.arena_id = t.arena_id and not cm.hidden and (cm.from_team = t.id or (cm.to_team = t.id and not exists (select 1 from chat_blocks cb where cb.team_id = t.id and cb.blocked_team = cm.from_team))) order by cm.at desc limit 80) m), '[]'::jsonb), 'blocked', coalesce((select jsonb_agg((select number from teams where id = blocked_team)) from chat_blocks where team_id = t.id), '[]'::jsonb) ) into v_comms; select coalesce(jsonb_agg(jsonb_build_object('for_team', (select number from teams where id = x.team_id), 'key', x.relay_key, 'deadline', x.deadline)), '[]'::jsonb) into v_out from mission_instances x where x.partner_team_id = t.id and x.status = 'active' and x.relay_key is not null; end if; if a.phase in ('lobby', 'boarding', 'shuttle', 'roles', 'play') then select coalesce(jsonb_agg(jsonb_build_object('number', number, 'name', name, 'points', points) order by points desc, number), '[]'::jsonb) into v_board from teams where arena_id = a.id and ready; end if; select jsonb_object_agg(r, (select display_name from players where team_id = t.id and active and role = r)) into v_role_names from unnest(array['captain', 'scout', 'decoder', 'intel']) r; return jsonb_build_object( 'server_now', now(), 'event', jsonb_build_object('name', e.name, 'code', e.code), 'me', jsonb_build_object('id', p.id, 'name', p.display_name, 'role', p.role), 'team', jsonb_build_object('id', t.id, 'number', t.number, 'name', t.name, 'hp', t.hp, 'shield', t.shield, 'coins', t.coins, 'points', t.points, 'trust', t.trust, 'location', t.location_id, 'state', t.state, 'travel_to', t.travel_to, 'travel_from', t.travel_from, 'travel_started_at', t.travel_started_at, 'travel_arrive_at', t.travel_arrive_at, 'recovery_deadline', t.recovery_deadline, 'attack_cooldown_until', t.attack_cooldown_until, 'protected_until', t.protected_until, 'jammed_until', t.jammed_until, 'scan_until', t.scan_until, 'beacon', t.beacon, 'ready', t.ready, 'bus', t.bus, 'dropped', t.dropped, 'visit_missions', t.visit_missions, 'visit_limit', _cfg(e.id, 'visit_missions'), 'pos', to_jsonb(_team_xy(t)), 'level', t.level, 'bldg', t.bldg, 'travel_from_xy', case when t.travel_fx is not null then jsonb_build_array(t.travel_fx, t.travel_fy) end), 'roster', (select coalesce(jsonb_agg(jsonb_build_object('name', display_name, 'role', role, 'online', last_seen_at > now() - interval '25 seconds', 'me', id = p.id) order by joined_at), '[]'::jsonb) from players where team_id = t.id and active), 'roles', v_role_names, 'arena', jsonb_build_object('id', a.id, 'number', a.number, 'name', a.name, 'phase', a.phase, 'paused', a.paused, 'shuttle_departed_at', a.shuttle_departed_at, 'shuttle_arrive_at', a.shuttle_arrive_at, 'roles_deadline', a.roles_deadline, 'zone_stage', a.zone_stage, 'zone_next_at', a.zone_next_at, 'finale_stage', a.finale_stage, 'overlay', a.overlay, 'threat', a.threat, 'results_locked', a.results_locked, 'winner_revealed', a.winner_revealed), 'mission', v_mission, 'battle', v_battle, 'last_result', v_result, 'squads', (select coalesce(jsonb_agg(jsonb_build_object( 'id', x.id, 'number', x.number, 'name', x.name, 'hp', x.hp, 'state', x.state, 'location', case when x.id = t.id or v_scan or x.location_id = t.location_id or x.jammed_until is null or x.jammed_until < now() or exists (select 1 from alliances al where al.status = 'active' and ((al.team_a = t.id and al.team_b = x.id) or (al.team_b = t.id and al.team_a = x.id))) then x.location_id end, 'pos', case when x.id = t.id or v_scan or x.location_id = t.location_id or x.jammed_until is null or x.jammed_until < now() or exists (select 1 from alliances al where al.status = 'active' and ((al.team_a = t.id and al.team_b = x.id) or (al.team_b = t.id and al.team_a = x.id))) then to_jsonb(_team_xy(x)) end, 'traveling', x.state = 'traveling', 'level', x.level, 'bldg', x.bldg, 'vel', case when x.state = 'idle' and x.pos_at > now() - interval '1500 milliseconds' then jsonb_build_array(x.vel_x, x.vel_y) end, 'protected', x.protected_until > now(), 'in_battle', exists (select 1 from battles bb where bb.status = 'active' and (bb.attacker_id = x.id or bb.defender_id = x.id)), 'allied', exists (select 1 from alliances al where al.status = 'active' and ((al.team_a = t.id and al.team_b = x.id) or (al.team_b = t.id and al.team_a = x.id))) ) order by x.number), '[]'::jsonb) from teams x where x.arena_id = t.arena_id and x.ready), 'airdrops', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'location', location_id, 'tier', tier, 'expires_at', expires_at)), '[]'::jsonb) from airdrops where arena_id = a.id and status = 'open'), 'pickups', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'k', kind, 'x', x, 'y', y, 'l', level)), '[]'::jsonb) from pickups where arena_id = a.id and taken_at is null), 'inventory', (select coalesce(jsonb_object_agg(item_id, qty), '{}'::jsonb) from inventory where team_id = t.id and qty > 0), 'comms', v_comms, 'codewords', v_out, 'alliances', (select coalesce(jsonb_agg(jsonb_build_object('id', al.id, 'status', al.status, 'expires_at', al.expires_at, 'other', (select number from teams where id = case when al.team_a = t.id then al.team_b else al.team_a end), 'incoming', al.proposed_by <> t.id) order by al.created_at desc), '[]'::jsonb) from alliances al where (al.team_a = t.id or al.team_b = t.id) and al.status in ('proposed', 'active')), 'bargains', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'title', s.title, 'body', s.body, 'offer', s.offer, 'expires_at', s.expires_at)), '[]'::jsonb) from story_events s where s.arena_id = a.id and s.kind = 'bargain' and coalesce(s.expires_at, now() + interval '1 second') > now() and not (t.bargains @> jsonb_build_array(jsonb_build_object('id', s.id::text)))), 'story', (select coalesce(jsonb_agg(jsonb_build_object('title', title, 'body', body, 'at', at) order by at desc), '[]'::jsonb) from (select * from story_events where arena_id = a.id and kind in ('transmission', 'reveal') order by at desc limit 3) s), 'feed', (select coalesce(jsonb_agg(jsonb_build_object('type', type, 'payload', payload, 'at', at) order by id desc), '[]'::jsonb) from (select * from game_feed where arena_id = a.id order by id desc limit 12) f), 'leaderboard', v_board, 'results', case when a.winner_revealed then a.results end ); end $$; create or replace function spectator_state(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare a arenas; e events; sr sync_rounds; v_recap jsonb; v_show_scores boolean; begin select * into a from arenas where spectator_token = p_token; if a.id is null or p_token is null or length(p_token) < 16 then raise exception 'SPECTATOR_AUTH'; end if; perform _tick(a.id); select * into a from arenas where id = a.id; select * into e from events where id = a.event_id; select * into sr from sync_rounds where id = a.sync_round_id; v_show_scores := a.phase in ('lobby', 'boarding', 'shuttle', 'roles', 'play'); if a.phase in ('finale', 'results', 'ended') and coalesce(a.finale_stage, 'A') >= 'D' then v_recap := jsonb_build_object( 'bargains_accepted', (select count(*) from teams t, jsonb_array_elements(t.bargains) b where t.arena_id = a.id and (b ->> 'accept')::boolean), 'bargains_refused', (select count(*) from teams t, jsonb_array_elements(t.bargains) b where t.arena_id = a.id and not (b ->> 'accept')::boolean), 'betrayals', (select count(*) from alliances where arena_id = a.id and status = 'betrayed'), 'alliances', (select count(*) from alliances where arena_id = a.id and status in ('active', 'ended', 'expired', 'betrayed') and expires_at > created_at and status <> 'expired'), 'codewords_shared', (select count(*) from ledger where arena_id = a.id and kind = 'relay_assist'), 'battles', (select count(*) from battles where arena_id = a.id), 'threat', a.threat, 'sealed', (select count(*) from lockdowns where arena_id = a.id and sealed), 'caught', (select count(*) from ledger where arena_id = a.id and kind = 'lockdown'), 'vaults', (select count(*) from airdrops where arena_id = a.id and tier = 'vault' and status = 'claimed'), 'loot', (select count(*) from pickups where arena_id = a.id and taken_at is not null)); end if; return jsonb_build_object( 'server_now', now(), 'event', jsonb_build_object('name', e.name, 'code', e.code, 'grand_revealed', e.grand_revealed), 'arena', jsonb_build_object('id', a.id, 'number', a.number, 'name', a.name, 'phase', a.phase, 'paused', a.paused, 'shuttle_departed_at', a.shuttle_departed_at, 'shuttle_arrive_at', a.shuttle_arrive_at, 'roles_deadline', a.roles_deadline, 'zone_stage', a.zone_stage, 'zone_next_at', a.zone_next_at, 'finale_stage', a.finale_stage, 'threat', a.threat, 'overlay', a.overlay, 'results_locked', a.results_locked, 'winner_revealed', a.winner_revealed), 'squads', (select coalesce(jsonb_agg(jsonb_build_object('number', t.number, 'name', t.name, 'ready', t.ready, 'bus', t.bus, 'players', (select count(*) from players where team_id = t.id and active), 'hp', t.hp, 'state', t.state, 'points', case when v_show_scores then t.points end, 'location', case when t.jammed_until is null or t.jammed_until < now() then t.location_id end, 'pos', case when t.jammed_until is null or t.jammed_until < now() then to_jsonb(_team_xy(t)) end, 'level', t.level, 'bldg', t.bldg, 'vel', case when t.state = 'idle' and t.pos_at > now() - interval '1500 milliseconds' then jsonb_build_array(t.vel_x, t.vel_y) end, 'travel_to', case when t.jammed_until is null or t.jammed_until < now() then t.travel_to end, 'travel_from', case when t.jammed_until is null or t.jammed_until < now() then t.travel_from end, 'travel_started_at', t.travel_started_at, 'travel_arrive_at', t.travel_arrive_at, 'in_battle', exists (select 1 from battles b where b.status = 'active' and (b.attacker_id = t.id or b.defender_id = t.id)), 'sync_solved', case when sr.id is not null then exists (select 1 from mission_instances mi where mi.sync_round_id = sr.id and mi.team_id = t.id and mi.status = 'solved') end ) order by t.number), '[]'::jsonb) from teams t where t.arena_id = a.id), 'airdrops', (select coalesce(jsonb_agg(jsonb_build_object('location', location_id, 'tier', tier, 'expires_at', expires_at)), '[]'::jsonb) from airdrops where arena_id = a.id and status = 'open'), 'pickups', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'k', kind, 'x', x, 'y', y, 'l', level)), '[]'::jsonb) from pickups where arena_id = a.id and taken_at is null), 'battles', (select coalesce(jsonb_agg(jsonb_build_object('attacker', (select number from teams where id = b.attacker_id), 'defender', (select number from teams where id = b.defender_id), 'weapon', b.weapon, 'location', b.location_id, 'x', b.x, 'y', b.y, 'deadline', b.deadline)), '[]'::jsonb) from battles b where b.arena_id = a.id and b.status = 'active'), 'sync', case when sr.id is not null then jsonb_build_object('kind', sr.kind, 'stage', sr.stage, 'deadline', sr.deadline, 'title', (select title from mission_templates where id = sr.template_id), 'solved', (select count(*) from mission_instances where sync_round_id = sr.id and status = 'solved'), 'total', (select count(*) from mission_instances where sync_round_id = sr.id)) end, 'story', (select coalesce(jsonb_agg(jsonb_build_object('kind', kind, 'title', title, 'body', body, 'at', at) order by at desc), '[]'::jsonb) from (select * from story_events where arena_id = a.id order by at desc limit 3) s), 'feed', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'type', type, 'payload', payload, 'at', at) order by id desc), '[]'::jsonb) from (select * from game_feed where arena_id = a.id order by id desc limit 30) f), 'recap', v_recap, 'results', case when a.winner_revealed then a.results end, 'grand', case when e.grand_revealed then _event_standings(e.id) end ); end $$; create or replace function map_data() returns jsonb language sql stable security definer set search_path = public as $$ select jsonb_build_object( 'locations', (select jsonb_agg(jsonb_build_object('id', id, 'name', name, 'building', building, 'floor', floor, 'level', level, 'x', x, 'y', y, 'kind', kind, 'collapse', collapse_stage, 'risk', risk, 'reward', reward, 'tags', tags, 'drop', drop_zone, 'enabled', enabled) order by id) from locations), 'buildings', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'name', name, 'x0', x0, 'y0', y0, 'x1', x1, 'y1', y1, 'floors', floors, 'stairs', jsonb_build_array(stair_x, stair_y), 'door', jsonb_build_array(door_x, door_y), 'style', style) order by id), '[]'::jsonb) from buildings), 'edges', (select jsonb_agg(jsonb_build_array(a, b, seconds)) from edges), 'items', (select jsonb_agg(jsonb_build_object('id', id, 'name', name, 'kind', kind, 'description', description, 'price', price, 'params', params) order by price) from items) ) $$;
